// Adding a new app-lifetime singleton cubit.
//
// Three locations to edit:
//   1. The cubit class file        — annotation + (optional) post-construct
//   2. (auto) injection.config.dart — regenerated by build_runner
//   3. lib/bootstrapper.dart       — provider entry in the right half
//
// Plus (sometimes):
//   4. lib/shared_main.dart        — pre-runApp initialize() call if needed
//
// ─── STEP 0: GET USER APPROVAL ───────────────────────────────────────────────
// Default cubits are @injectable (factory). @singleton requires explicit user
// approval — singletons hold app-lifetime state and have wide blast radius.
// Don't reach for @singleton because "I only need one of them" — that's what
// the DI container's caching already does for @injectable when scoped to a
// BlocProvider. Reach for @singleton when:
//   • The cubit holds state that must survive page navigation
//   • The cubit owns a long-lived stream subscription (refresh bus, auth state)
//   • The cubit is a HydratedCubit (owns the persistence contract)
//   • The router redirect or composition root reads it synchronously

// ─── STEP 1: The cubit class ─────────────────────────────────────────────────
//
// Pick the annotation:
//   @singleton          — eager, constructed at getIt.init()
//   @lazySingleton      — first-resolve, may never construct
//   @singletonAsync     — needs async setup (or use @PostConstruct on @singleton)
//   @Environment('dev') — dev-only registration; combine with above

import 'package:injectable/injectable.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

@singleton
class ExperimentsCubit extends Cubit<ExperimentsState> {
  ExperimentsCubit(this._repository) : super(const ExperimentsState());

  final ExperimentsRepository _repository;

  /// Called by the bootstrapper via the `..initialize()` cascade.
  /// Subscribes to remote-config updates; the subscription lives for the
  /// app's lifetime (which is why this is @singleton — survives every
  /// navigation, owns the stream).
  void initialize() {
    _repository.experimentsStream.listen((flags) {
      emit(state.copyWith(flags: flags));
    });
  }
}

// ─── STEP 2: Rebuild DI ──────────────────────────────────────────────────────
//
// dart run build_runner build --delete-conflicting-outputs
//
// This regenerates injection.config.dart with the new singleton registration.

// ─── STEP 3: Bootstrapper provider entry ─────────────────────────────────────
//
// In bootstrapper.dart, decide which half:
//
//   MultiRepositoryProvider — plain services + cubits the UI does NOT
//                              BlocBuilder against (router redirect only)
//   MultiBlocProvider       — cubits the UI rebuilds against
//
// ExperimentsCubit drives feature flags that UI conditionally renders against,
// so it goes in MultiBlocProvider:
//
//   BlocProvider.value(value: getIt<ExperimentsCubit>()..initialize()),
//
// Use .value (not create:) because this is the composition root and the
// canonical instance lives in DI. Add the `..initialize()` cascade if the
// cubit has a kick-off method.

// ─── STEP 4 (if applicable): Pre-runApp init ─────────────────────────────────
//
// If the cubit needs work done BEFORE runApp (e.g., to capture cold-start
// state or to be ready before the first frame), add to shared_main.dart in
// the correct ordering slot. For ExperimentsCubit the constructor-time
// subscription is enough — no pre-runApp init needed.
//
// If it WERE needed, the slot would be after configureDependencies (so DI is
// ready) and before runApp:
//
//   await configureDependencies();
//   await getIt<ExperimentsCubit>().fetchInitialFlags();   // <-- new step
//   final startupPipelineConfig = await _buildStartupPipelineConfig();
//   await getIt<DeepLinkService>().initialize();
//   // ...runApp...

// Stand-ins so the template type-checks. Real versions live in your feature.
class ExperimentsState {
  const ExperimentsState({this.flags = const {}});
  final Map<String, bool> flags;
  ExperimentsState copyWith({Map<String, bool>? flags}) =>
      ExperimentsState(flags: flags ?? this.flags);
}

abstract class ExperimentsRepository {
  Stream<Map<String, bool>> get experimentsStream;
}
